    "claims": [
      {
        "id": "c1",
        "text": "写文件操作成功创建了 out.txt，共 10 字节。",
        "status": "verified",
        "sources": [
          "/tmp/1ash-m1-coding-command-jzah4_gq/out.txt"
        ],
        "scope": null
      },
      {
        "id": "c2",
        "text": "读回文件内容为 hello 1ash，没有多余空白或末尾换行。",
        "status": "verified",
        "sources": [
          "/tmp/1ash-m1-coding-command-jzah4_gq/out.txt"
        ],
        "scope": null
      },
      {
        "id": "c3",
        "text": "文件字节数与 hello 1ash 的 10 个字符一致，说明未加换行符。",
        "status": "derived",
        "sources": [
          "/tmp/1ash-m1-coding-command-jzah4_gq/out.txt"
        ],
        "scope": "依据 10 字节的实测大小与内容读回推断"
      },
      {
        "id": "c4",
        "text": "独立校验器接受了这次交付，公共与隐藏标准均通过。",
        "status": "verified",
        "sources": [
          "acceptance_gate:a91b89918d2962b29620e5f017c932464e14fd48288566349b955f84907f53d6"
        ],
        "scope": null
      }
    ],
    "evidence": [
      {
        "source": "/tmp/1ash-m1-coding-command-jzah4_gq/out.txt",
        "statement": "write_file 回执：created=true，bytes=10，sha256=8b8b1418102cf064981c0a2b5e89f4fd73dae8bc003fa674590c3e560be5170a。",
        "observed_unix_ms": null,
        "expires_unix_ms": null,
        "claim_ids": [
          "c1"
        ]
      },
      {
        "source": "/tmp/1ash-m1-coding-command-jzah4_gq/out.txt",
        "statement": "read_file 读回内容为 hello 1ash，bytes=10，truncated=false。",
        "observed_unix_ms": null,
        "expires_unix_ms": null,
        "claim_ids": [
          "c2"
        ]
      },
      {
        "source": "/tmp/1ash-m1-coding-command-jzah4_gq/out.txt",
        "statement": "verify_artifact 返回 decision=verified，exists=true，checks 为 exists 与 non-empty，sha256 与写入时一致。",
        "observed_unix_ms": null,
        "expires_unix_ms": null,
        "claim_ids": [
          "c3"
        ]
      },
      {
        "source": "acceptance_gate:a91b89918d2962b29620e5f017c932464e14fd48288566349b955f84907f53d6",
        "statement": "acceptance_gate 返回 decision=accepted，public_passed=true，hidden_passed=true，failures 为空。",
        "observed_unix_ms": null,
        "expires_unix_ms": null,
        "claim_ids": [
          "c4"
        ]
      }
    ],
    "assumptions": [
      {
        "description": "用户要的“精确文本”指文件只含这 10 个字符，不含末尾换行。",
        "impact": "low",
        "verification_method": "若需要 POSIX 行尾，重新写入并在末尾追加 \\n 后再次读回校验。"
      }
    ],
    "constraints": [
      "写入范围限定在 /tmp/1ash-m1-coding-command-jzah4_gq 下。",
      "文件名固定为 out.txt。"
    ],
    "unknowns": [
      {
        "id": "u1",
        "description": "下游使用方是否要求文件以换行结尾。",
        "impact": "low",
        "why_it_matters": "影响某些按行读取的工具是否把该文件当成完整一行。",
        "reduction_method": "确认使用方的读取方式，或按需补一个换行符。"
      }
    ],
    "conflicts": [],
    "flip_conditions": [
      {
        "if_observed": "读回内容不是 hello 1ash，或字节数不是 10。",
        "then": "c2 和 c3 不成立，交付应判为未完成并重写文件。",
        "target_ids": [
          "c2",
          "c3"
        ]
      },
      {
        "if_observed": "校验器返回 rejected 或 conditional。",
        "then": "c4 不成立，不能声称交付已被接受。",
        "target_ids": [
          "c4"
        ]
      }
    ],
    "action_receipts": [
      "write_file /tmp/1ash-m1-coding-command-jzah4_gq/out.txt -> created=true, bytes=10, sha256=8b8b1418102cf064981c0a2b5e89f4fd73dae8bc003fa674590c3e560be5170a",
      "verify_artifact /tmp/1ash-m1-coding-command-jzah4_gq/out.txt -> decision=verified, sha256=8b8b1418102cf064981c0a2b5e89f4fd73dae8bc003fa674590c3e560be5170a"
    ],
    "task_need": {
      "freshness": "none",
